/* Learn English — topics, their lesson, and practice exercises.

   Topic: { id, title, titleEn, lesson | lessons, lessonSummary?, lessonSummaryEn?, presentations?, exercises, group?, cover? }
   - group: the topic grid section — "grammar" (default), "vocab" (built at
     the end of this file from english-vocab.js) or "reading" (the reading
     library, added by english-reading.js). cover: a vocab picture id for the tile.
   - Reading passages ("reading" exercises) are added by english-reading.js.
   - lesson: id of a ready-lesson (ready-lessons.js LESSON_CATALOG) — opens in
     the same lesson player as the lessons library.
   - lessons: the topic split into short numbered lessons, in order (instead
     of `lesson`); each one's card shows "שיעור N" and its own summary.
   - presentations (optional): extra image-based decks for the slide viewer.
       { id, title, titleEn, slides: ["/images/english/<topic>/slide-1.png", ...] }

   Exercise types (every exercise: id, type, title, titleEn, instructions,
   instructionsEn, roundSize — questions per round, drawn at random):
   - choice:       pick the word for the blank (___).
                   options: [...] shared buttons, or per-question `options`
                   (shuffled). questions: [{ text, hint?, context?, answer, options?, he? }]
   - truefalse:    is the sentence correct? questions: [{ text, correct, fix?, he? }]
   - write:        type the missing word. questions: [{ text, hint?, answer, accept?, he? }]
                   or `words: [vocab ids]` to spell the word for a picture.
     `he` on choice / truefalse / write is the Hebrew translation shown under
     the sentence when the translation toggle is on. It keeps a ___ blank
     wherever translating the tested word would give the answer away; for a
     wrong true/false sentence it translates the intended (fixed) meaning.
   - order:        tap the words into the right order. questions: [{ answer, he? }]
   - picture:      see a picture, choose the word.   words: [vocab ids]
   - pick-picture: read a word, choose the picture.  words: [vocab ids]
   - listen:       hear a word, choose the picture.  words: [vocab ids]
   - match:        match pairs. pairs: [{ a, b }] or words: [vocab ids]
                   (word ↔ picture); boardSize = pairs per board. */

